import 'package:cryptography/cryptography.dart';

final algorithm = AesGcm.with256bits();
final secretKey = await algorithm.newSecretKey();
final nonce = algorithm.nonceLength;
final secretMessage = [1,2,3];
final encrypted = await algorithm.encrypt(secretMessage, secretKey: secretKey);
final decrypted = await algorithm.decrypt(encrypted, secretKey: secretKey);
print('Decrypted: $decrypted');
